import sys; sys.path.insert(0, '/workspace/derm-teach/website/tools/v4/authoring'); from enr import *

E('urticaria-angioedema',
  kf=["**Urticaria**: itchy, transient **weals** (each lasting < 24 h) from mast-cell mediator release; **angioedema** is deeper swelling lasting up to 72 h.",
      "About **1 in 5** people have acute urticaria in their lifetime; chronic spontaneous urticaria affects **0.5–2%**.",
      "Acute (< 6 weeks) is often triggered by infection, drugs or food; chronic (≥ 6 weeks) is usually spontaneous or inducible.",
      "UK first line: a **non-sedating second-generation antihistamine**, increased up to 4 times the licensed dose (off-label) under guidance.",
      "Angioedema **without weals** (ACE inhibitor, hereditary) is bradykinin-mediated and does not respond to antihistamines; airway swelling is an emergency."],
  epi=[{"t": "**Acute urticaria**", "sub": ["About 20% lifetime prevalence; all ages and both sexes.", "In children usually triggered by **viral infection**; in adults often idiopathic."]},
       {"t": "**Chronic urticaria**", "sub": ["Chronic spontaneous urticaria affects **0.5–2%**, about two thirds women, peak 20–40 years.", "Chronic inducible (physical) urticarias such as dermographism are more common."]},
       {"t": "**Duration**", "sub": ["Chronic spontaneous urticaria lasts on average 2–5 years; about half clear within a year."]}],
  aet=["**Acute triggers**: viral or bacterial infection, **drugs** (NSAIDs, aspirin, antibiotics, opioids), IgE-mediated food allergy (milk, egg, peanut, shellfish), insect stings.",
       "**Chronic spontaneous**: autoimmune (IgG autoantibodies to IgE or its receptor FcεRI, or IgE to self-antigens) in about half; associated with autoimmune thyroid disease.",
       "**Inducible**: dermographism, cold, cholinergic (heat, sweat), pressure, solar, aquagenic, vibratory.",
       "**Aggravators**: NSAIDs, alcohol, heat, stress, tight clothing."],
  myths=["**\"Chronic hives must be an allergy\"**: chronic spontaneous urticaria is rarely allergic; extensive allergy testing is not helpful.",
         "**\"All swelling responds to antihistamines\"**: bradykinin angioedema (ACE inhibitor, hereditary angioedema) does not."],
  patho_lead="Weals come from **mast cells** in the dermis releasing histamine and other mediators; angioedema is the same process deeper down (or bradykinin-driven).",
  mech=[("Mast cells are activated", "Triggers (IgE cross-linking by allergen, autoantibodies to FcεRI, complement, drugs, physical stimuli) activate dermal **mast cells** and basophils."),
        ("Mediators are released", "Mast cells degranulate, releasing **histamine**, prostaglandin D2, leukotrienes, platelet-activating factor and cytokines."),
        ("Vessels leak, nerves itch", "Histamine dilates and opens small vessels (**oedema and redness**: the weal and flare) and stimulates sensory nerves (**itch**).", "v3-urticaria-sections.jpg", "Weal (superficial dermal oedema) vs angioedema (oedema of deep dermis and subcutis)."),
        ("Deeper swelling: angioedema", "The same leak in the **deep dermis, subcutis or mucosa** gives angioedema; **bradykinin** causes non-itchy angioedema without weals (ACE inhibitors, C1-inhibitor deficiency).", "v3-angioedema-face.jpg", "Angioedema of the lips and eyelids."),
        ("Weals resolve", "Mediators are cleared within hours, so each weal fades within 24 hours without marks; lesions lasting longer or bruising suggest **urticarial vasculitis**.")],
  histo=["Dermal oedema with dilated vessels and a sparse perivascular infiltrate (neutrophils, eosinophils, lymphocytes); epidermis normal.",
         "Biopsy only if weals last over 24 hours, burn or bruise (to exclude urticarial vasculitis)."],
  special=[{"t": "**Skin of colour**", "sub": ["Weals may look skin-coloured or slightly darker rather than red; rely on raised, itchy, transient swellings."]},
           {"t": "**Pregnancy and breastfeeding**", "sub": ["Loratadine or cetirizine are usually preferred (check BNF)."]}],
  comp=["**Anaphylaxis** (with respiratory or circulatory compromise).",
        "Airway compromise from laryngeal or tongue angioedema.",
        "Sleep loss, poor quality of life, anxiety and depression in chronic urticaria."],
  prog=["Acute urticaria usually settles within days to weeks.",
        "Chronic spontaneous urticaria: about 50% remit within a year; some persist for more than 5 years."],
  see_also=["ace-inhibitor-angioedema", "urticarial-vasculitis", "papular-urticaria-bites"])

E('rosacea',
  kf=["Chronic inflammatory facial disease with **flushing, persistent central redness, papules and pustules** and telangiectasia; **no comedones**.",
      "Affects about **5%** of adults, usually after 30; men and women about equally (phymas mainly men).",
      "Driven by neurovascular hyper-reactivity, innate immune activation (cathelicidin/LL-37) and *Demodex*.",
      "UK: trigger avoidance and sun protection; **ivermectin 1%**, azelaic acid or metronidazole for papules; **brimonidine** for redness; oral doxycycline for moderate–severe.",
      "**Ocular rosacea** with pain or reduced vision needs urgent eye review."],
  epi=[{"t": "**Prevalence**", "sub": ["About **5%** of adults worldwide; under-recognised in skin of colour."]},
       {"t": "**Age and sex**", "sub": ["Usually presents **after 30** and becomes commoner with age; roughly equal sex distribution; **rhinophyma** is mainly in men."]},
       {"t": "**Skin type**", "sub": ["Most common in fair skin (Celtic and Northern European descent)."]},
       {"t": "**Associations**", "sub": ["Depression, anxiety, migraine, cardiovascular disease, inflammatory bowel disease and *H. pylori* have been linked."]}],
  aet=["**Genetic** susceptibility (HLA class II polymorphisms; family history).",
       "**Triggers**: UV light, heat and cold, exercise, hot drinks, spicy food, **alcohol**, stress, cosmetics, **topical steroids**.",
       "**Microbes**: increased *Demodex folliculorum* density; *Bacillus oleronius*; *S. epidermidis*."],
  myths=["**\"Rosacea is adult acne\"**: no comedones; acne treatments such as benzoyl peroxide often irritate.",
         "**\"Red nose means alcoholism\"**: rhinophyma occurs in non-drinkers; alcohol is just one trigger."],
  patho_lead="Rosacea combines an **over-reactive innate immune system** with **unstable facial blood vessels and nerves**.",
  mech=[("Triggers activate the skin", "UV, heat, spicy food, alcohol and *Demodex* activate **TLR2** receptors on keratinocytes."),
        ("Cathelicidin overdrive", "Raised **kallikrein-5** cleaves cathelicidin into **LL-37**, which drives inflammation, vasodilatation and new vessel growth."),
        ("Neurovascular reactivity", "Sensory nerves (TRPV1 channels) release neuropeptides such as **CGRP**, causing **flushing**, burning and stinging; repeated flushing leaves **persistent erythema** and telangiectasia.", "v3-rosacea-skin-section.jpg", "Rosacea skin: dilated vessels, inflamed follicles and Demodex mites in the dermis."),
        ("Papules and pustules", "Inflammatory cells gather around follicles, producing papules and sterile pustules (no comedones)."),
        ("Phyma and fibrosis", "Chronic inflammation and lymphatic leakage cause sebaceous hyperplasia and fibrosis, thickening the nose (**rhinophyma**).", "v3-rosacea-face-map.jpg", "Central face distribution: cheeks, nose, chin and forehead.")],
  histo=["Dilated dermal vessels, solar elastosis and a perivascular and perifollicular lymphohistiocytic infiltrate.",
         "Papulopustular: perifollicular inflammation, sometimes granulomas; increased *Demodex*.",
         "Phymatous: sebaceous hyperplasia, fibrosis and dilated follicles. Biopsy is rarely needed."],
  special=[{"t": "**Skin of colour**", "sub": ["Redness may be hard to see; warmth, papules, burning and dryness are clues; granulomatous forms may be more common."]},
           {"t": "**Children**", "sub": ["Rare; ocular symptoms may come first; consider perioral dermatitis."]}],
  comp=["**Ocular rosacea**: blepharitis, conjunctivitis, keratitis, rarely corneal ulceration.",
        "**Rhinophyma** and other phymas.", "Psychological distress, low self-esteem and social avoidance."],
  prog=["Chronic and relapsing; treatment controls rather than cures.", "Persistent erythema and telangiectasia respond best to vascular lasers or IPL (not on the NHS routinely)."],
  see_also=["acne-mimics", "acne-vulgaris", "topical-corticosteroids", "discoid-lupus"])

E('contact-dermatitis',
  kf=["Eczema caused by something touching the skin: **irritant (ICD, about 80%)** or **allergic (ACD, type IV delayed hypersensitivity)**.",
      "Hands and face are the commonest sites; occupational exposure is frequent (hairdressers, healthcare, cleaners, builders).",
      "ACD: about **25 allergens** cause half of cases; nickel is the leading cause worldwide.",
      "Identify and avoid the cause (**patch testing** for suspected ACD), emollients and soap substitutes, topical steroid.",
      "Persistent occupational dermatitis may need specialist and occupational health input."],
  epi=[{"t": "**Common**", "sub": ["Contact dermatitis accounts for most **occupational skin disease**; irritant contact dermatitis is about four times commoner than allergic."]},
       {"t": "**Who**", "sub": ["Any age; more common in adults with wet work; atopic people are at higher risk of irritant dermatitis.", "Nickel allergy is commonest in women (jewellery, piercings) but falling in Europe since the EU Nickel Directive."]}],
  aet=["**Irritants**: water and wet work, soaps and detergents, solvents, friction, cutting oils, alkalis and acids.",
       "**Common allergens**: nickel, cobalt, chromate (cement, leather), fragrances, preservatives (**methylisothiazolinone**, formaldehyde releasers), **PPD** hair dye, rubber accelerators, topical medicines (neomycin, corticosteroids), plants (*Primula*, Compositae).",
       "A damaged barrier (e.g. atopic eczema, leg ulcers, perianal disease) increases sensitisation to topical medicines."],
  myths=["**\"I've used it for years, so I can't be allergic\"**: sensitisation can develop after years of exposure.",
         "**\"Hypoallergenic products are safe\"**: they can still contain relevant allergens."],
  patho_lead="**Irritant** dermatitis is direct damage; **allergic** dermatitis is a learned T-cell response.",
  mech=[("Irritant damage", "Irritants strip lipids and damage keratinocytes directly, causing barrier loss and non-specific inflammation in anyone exposed enough; no prior sensitisation needed.", "v3-contact-icd-acd.jpg", "Irritant dermatitis (direct damage) vs allergic dermatitis (sensitised T cells)."),
        ("Sensitisation phase (allergic)", "Small reactive chemicals (**haptens**, under 500 Da) bind skin proteins; Langerhans cells carry them to lymph nodes and prime specific **T cells** (10–15 days)."),
        ("Elicitation phase", "On re-exposure, memory T cells release cytokines at the contact site within **24–72 hours**, causing eczema (type IV hypersensitivity)."),
        ("Spread and chronicity", "Eczema can spread beyond the contact area (autosensitisation); continued exposure leads to chronic, lichenified, fissured dermatitis.")],
  histo=["Spongiotic dermatitis (intercellular oedema, vesicles) with lymphocytes; eosinophils favour allergic dermatitis.",
         "Irritant: keratinocyte necrosis and neutrophils in acute damage. Histology cannot identify the cause: **patch testing** does."],
  dist=["**Hands** (wet work, gloves, occupational).", "**Face, eyelids and neck** (cosmetics, airborne allergens, nail varnish).",
        "**Earlobes, wrists and umbilicus** (nickel).", "**Scalp margin and face** (hair dye PPD).", "**Feet** (shoes: chromate, rubber)."],
  comp=["Chronic hand dermatitis with loss of work; secondary bacterial infection.",
        "Severe facial and scalp swelling after PPD hair dye.", "Spread (autosensitisation) and erythroderma (rare)."],
  prog=["ICD improves when exposure stops, but barrier recovery takes weeks to months.",
        "ACD is lifelong: avoidance prevents recurrence; occupational ACD can persist even after avoidance."],
  see_also=["hand-eczema", "eczema-dermatitis", "emollients", "topical-corticosteroids"])

E('scabies',
  kf=["Infestation with the mite ***Sarcoptes scabiei*** var. *hominis*, spread by **prolonged skin-to-skin contact**.",
      "Intensely **itchy, worse at night**; burrows in finger webs, wrists, genitals; household members often affected.",
      "Itch is a hypersensitivity reaction starting **3–6 weeks** after first infestation (1–3 days on re-infestation).",
      "UK: **permethrin 5% cream** (malathion 0.5% aqueous if unsuitable), applied to the **whole body**, repeated after 7 days; treat **all close contacts at the same time**.",
      "**Crusted scabies** (immunosuppressed, frail) is highly contagious: specialist input."],
  epi=[{"t": "**Global burden**", "sub": ["About **200 million** people affected at any time; common in crowded and low-resource settings."]},
       {"t": "**In the UK**", "sub": ["Family outbreaks, schools and **care homes**; sexual spread in young adults.", "Most common in children, adolescents and older people."]}],
  aet=["**Transmission**: prolonged skin contact (family, sexual partners, carers); fomites matter mainly in **crusted scabies**.",
       "Risk factors: crowding, care homes, immunosuppression (HIV, steroids), cognitive impairment or reduced sensation (cannot scratch)."],
  myths=["**\"Scabies means dirt\"**: it spreads by contact, regardless of hygiene.",
         "**\"Still itching, so treatment failed\"**: itch can persist for **up to 4–6 weeks** after successful treatment."],
  patho_lead="The female mite lives in the **stratum corneum**; most symptoms come from the host's **allergic reaction** to mites and their products.",
  mech=[("Mating and burrowing", "After mating on the skin surface, the female burrows into the stratum corneum at 0.5–5 mm a day for her 4–8 week life.", "v3-scabies-burrow.jpg", "A female mite at the end of a burrow in the stratum corneum, with eggs and faeces behind her."),
        ("Eggs and the life cycle", "She lays **2–3 eggs a day**; larvae hatch in 2–5 days and become adults in about 2 weeks. A typical patient carries only **10–15 mites**."),
        ("Delayed hypersensitivity", "Mites, eggs and faeces (scybala) trigger a **type IV** reaction: generalised itch and papules appear 3–6 weeks after first infestation."),
        ("Crusted scabies", "With poor T-cell immunity or inability to scratch, mites multiply to **thousands or millions**, producing thick crusts and very high contagiousness."),
        ("Distribution", "Mites prefer thin skin with few hair follicles: finger webs, wrists, elbows, axillae, genitals and breasts.", "v3-scabies-map.jpg", "Typical sites: finger webs, wrists, elbows, axillae, waist, buttocks, genitals; head spared in adults.")],
  histo=["Mite, eggs or scybala within the stratum corneum (if biopsied), with a dermal infiltrate rich in **eosinophils**.",
         "Diagnosis is clinical or by **dermoscopy** (delta-wing sign) or skin scraping microscopy."],
  special=[{"t": "**Infants**", "sub": ["Palms, soles, face and scalp can be involved; vesicles and nodules; treat the head and face too."]},
           {"t": "**Older people and care homes**", "sub": ["Atypical presentation with little visible rash; crusted scabies may be missed: outbreak management with the health protection team."]},
           {"t": "**Skin of colour**", "sub": ["Papules and nodules may look brown or violaceous; post-inflammatory hyperpigmentation is common."]}],
  comp=["**Secondary bacterial infection** (impetigo, cellulitis), with post-streptococcal glomerulonephritis in endemic settings.",
        "**Nodular scabies**: itchy nodules that persist for months.", "Post-scabetic itch and eczema.",
        "Crusted scabies with institutional outbreaks."],
  prog=["Cured with correct treatment of the patient and all contacts; reinfestation is common if contacts are missed.",
        "Itch settles over 2–6 weeks; nodules can take longer."],
  see_also=["head-lice", "papular-urticaria-bites", "eczema-dermatitis"])
